type TreeNode = { v: number; L: TreeNode | null; R: TreeNode | null };
// Level-order array, null for a missing child.
function buildTree(values: (number | null)[]): TreeNode | null {
  if (!values.length || values[0] == null) return null;
  const root: TreeNode = { v: values[0], L: null, R: null };
  const q = [root];
  let i = 1;
  while (q.length && i < values.length) {
    const cur = q.shift()!;
    const l = values[i++];
    if (l != null) { cur.L = { v: l, L: null, R: null }; q.push(cur.L); }
    const r = values[i++];
    if (r != null) { cur.R = { v: r, L: null, R: null }; q.push(cur.R); }
  }
  return root;
}

function isValidIndex(root: TreeNode | null): boolean {
  const check = (n: TreeNode | null, low: number, high: number): boolean => {
    if (!n) return true;
    if (n.v <= low || n.v >= high) return false;
    return check(n.L, low, n.v) && check(n.R, n.v, high);
  };
  return check(root, -Infinity, Infinity);
}

function isValidIndexFrom(values: (number | null)[]): boolean {
  return isValidIndex(buildTree(values));
}
